1	package world
2	
3	import (
4		"bytes"
5		"crypto/rand"
6		"crypto/sha256"
7		"encoding/hex"
8		"encoding/json"
9		"errors"
10		"fmt"
11		"io"
12		"os"
13		"path/filepath"
14		"unicode/utf8"
15	)
16	
17	// RecordID 是一次成功保存产生的、在同一存档目录内唯一的记录标识。
18	type RecordID string
19	
20	// archiveFormatVersion 是存档目录布局版本，写入目录标记中。
21	const archiveFormatVersion = 1
22	
23	// recordFormatVersion 是当前唯一支持的记录格式版本。记录格式与存档目录
24	// 布局版本是两个独立的编号：目录可打开不代表其中每条记录都能被理解，
25	// 格式编号不是该值的记录（缺失、零、负值或其他正整数）一律按损坏处理，
26	// 即使其校验和匹配、世界状态合法。
27	const recordFormatVersion = 1
28	
29	// envelope 是记录文件在磁盘上的完整编码。
30	type envelope struct {
31		// Format 是记录格式版本。
32		Format int `json:"format"`
33		// ID 是本条记录的唯一标识。
34		ID RecordID `json:"id"`
35		// Parent 是父记录标识；直接建立的槽首条记录为空。
36		Parent RecordID `json:"parent,omitempty"`
37		// SlotFirst 标记本条记录是否为其所在槽的首条记录
38		// （直接建立的根记录，或从其他槽分出的分支记录）。
39		SlotFirst bool `json:"slotFirst"`
40		// Checksum 是对（格式版本、ID、父记录、首记录标记、完整世界状态）
41		// 计算出的内容校验和，因此父记录关系也被纳入校验。
42		Checksum string `json:"checksum"`
43		// State 是完整世界数据：种子、规则与全部状态。
44		State State `json:"state"`
45	}
46	
47	// checksumPayload 是参与校验和计算的规范内容。
48	type checksumPayload struct {
49		Format    int      `json:"format"`
50		ID        RecordID `json:"id"`
51		Parent    RecordID `json:"parent"`
52		SlotFirst bool     `json:"slotFirst"`
53		State     State    `json:"state"`
54	}
55	
56	func computeChecksum(e *envelope) string {
57		p := checksumPayload{
58			Format:    e.Format,
59			ID:        e.ID,
60			Parent:    e.Parent,
61			SlotFirst: e.SlotFirst,
62			State:     e.State,
63		}
64		// encoding/json 对 map 按键排序输出，同一状态总是得到相同字节。
65		b, _ := json.Marshal(p)
66		sum := sha256.Sum256(b)
67		return hex.EncodeToString(sum[:])
68	}
69	
70	// newRecordID 产生目录内唯一的记录标识。
71	func newRecordID() (RecordID, error) {
72		var b [16]byte
73		if _, err := rand.Read(b[:]); err != nil {
74			return "", err
75		}
76		return RecordID("r" + hex.EncodeToString(b[:])), nil
77	}
78	
79	func recordPath(dir string, id RecordID) string {
80		return filepath.Join(dir, "records", string(id)+".json")
81	}
82	
83	// writeRecord 将一条记录以“先临时文件后原子改名”的方式落盘，
84	// 并校验目标文件名此前不存在，保证记录标识不会复用或混写。
85	func writeRecord(slotDir string, e *envelope) error {
86		final := recordPath(slotDir, e.ID)
87		data, err := json.MarshalIndent(e, "", "  ")
88		if err != nil {
89			return err
90		}
91	
92		// O_EXCL：即便极小概率撞到重复 ID，也绝不会覆盖别的记录。
93		f, err := os.OpenFile(final+".tmp",
94			os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
95		if err != nil {
96			return err
97		}
98		tmpName := f.Name()
99		clean := true
100		defer func() {
101			if clean {
102				os.Remove(tmpName)
103			}
104		}()
105	
106		if _, err := f.Write(data); err != nil {
107			f.Close()
108			return err
109		}
110		if err := f.Sync(); err != nil {
111			f.Close()
112			return err
113		}
114		if err := f.Close(); err != nil {
115			return err
116		}
117		if err := os.Rename(tmpName, final); err != nil {
118			return err
119		}
120		clean = false
121		if err := syncDir(filepath.Dir(final)); err != nil {
122			return err
123		}
124		return nil
125	}
126	
127	// loadRecord 读取并解析一条记录文件，但不做校验。
128	//
129	// 解析前先做文本编码检查：encoding/json 会把记录中的无效 UTF-8 字节和
130	// 字符串值、对象键里不成对的 Unicode 代理项转义悄悄改写成替换字符“�”，
131	// 随后才做内容校验——若原记录本就含有合法的“�”，改写后的文本甚至可能
132	// 仍通过校验和检查，文件损坏便被掩盖。因此无效字节与不成对的代理项转义
133	// 必须在解析前按原始字节拒绝，整条记录视为损坏，绝不用替换字符补齐后
134	// 继续交付。
135	//
136	// 解析后还要检查同一对象内的名称是否重复出现：encoding/json 对同名字段
137	// 静默采用后一个值，只要解码后的内容与校验和匹配，一份内部自相矛盾的
138	// 记录（例如先写一个负的时间片、再用同名字段写回合法值）就会被当作完好
139	// 记录交付。因此同一对象内任何名称出现第二次，无论两个值是否相同、采用
140	// 后一个值后的世界是否合法、校验和是否匹配，整条记录都视为损坏。
141	func loadRecord(path string) (*envelope, error) {
142		f, err := os.Open(path)
143		if err != nil {
144			return nil, err
145		}
146		defer f.Close()
147		data, err := io.ReadAll(f)
148		if err != nil {
149			return nil, err
150		}
151		if err := checkRecordText(data); err != nil {
152			return nil, err
153		}
154		var e envelope
155		if err := json.Unmarshal(data, &e); err != nil {
156			return nil, fmt.Errorf("记录无法解析: %w", err)
157		}
158		if err := checkDuplicateNames(data); err != nil {
159			return nil, err
160		}
161		return &e, nil
162	}
163	
164	// checkDuplicateNames 检查 JSON 文本中同一对象内的名称是否重复出现。
165	//
166	// 名称按 JSON 转义还原后的字符串比较：直接写出的名称与表示同一名称的
167	// Unicode 转义（如 "ID" 与写作转义形式的同一名称）视为同一名称，不能
168	// 借此绕过限制。
169	// 判定严格按对象边界：两个不同对象各自使用相同名称是正常的（例如两个物品
170	// 条目各自有数量字段），只有同一对象内名称第二次出现才报错；字符串值中的
171	// 文字与标点不算对象名称。记录文本已经通过 json.Unmarshal 解析，这里只做
172	// 重复名称判定，语法问题不再出现。
173	func checkDuplicateNames(data []byte) error {
174		dec := json.NewDecoder(bytes.NewReader(data))
175		// UseNumber 避免数值范围差异：这里只关心对象结构与名称，不解释数值。
176		dec.UseNumber()
177		// frame 描述解析栈中的一层容器：对象记录已见过的名称并跟踪下一个
178		// token 是否为键；数组只需占位，其中的字符串是值而不是名称。
179		type frame struct {
180			isObj     bool
181			seen      map[string]bool
182			expectKey bool
183		}
184		var stack []*frame
185		// 一个值（标量或容器）结束后，父对象等待下一个键。
186		markValueDone := func() {
187			if n := len(stack); n > 0 && stack[n-1].isObj {
188				stack[n-1].expectKey = true
189			}
190		}
191		for {
192			tok, err := dec.Token()
193			if err != nil {
194				// 文本已通过 json.Unmarshal，正常只会遇到 io.EOF；其余
195				// 情况不在这里报告。
196				return nil
197			}
198			if n := len(stack); n > 0 && stack[n-1].isObj && stack[n-1].expectKey {
199				if d, ok := tok.(json.Delim); ok && d == '}' {
200					stack = stack[:n-1]
201					continue
202				}
203				key, ok := tok.(string)
204				if !ok {
205					return nil
206				}
207				if stack[n-1].seen[key] {
208					return fmt.Errorf("同一对象内名称 %q 重复出现", key)
209				}
210				stack[n-1].seen[key] = true
211				stack[n-1].expectKey = false
212				continue
213			}
214			switch d := tok.(type) {
215			case json.Delim:
216				switch d {
217				case '{':
218					markValueDone()
219					stack = append(stack, &frame{isObj: true, seen: make(map[string]bool), expectKey: true})
220				case '[':
221					markValueDone()
222					stack = append(stack, &frame{})
223				case '}', ']':
224					stack = stack[:len(stack)-1]
225				}
226			default:
227				markValueDone()
228			}
229		}
230	}
231	
232	// checkRecordText 校验记录文件原始字节的文本编码：JSON 文本必须是合法
233	// UTF-8；字符串值与对象键中的 \uXXXX 转义若是代理项，必须完整配对——
234	// 高位代理项（D800–DBFF）后必须紧接一个低位代理项转义（DC00–DFFF），
235	// 低位代理项不得单独出现。合法内容不受影响：真实存在的“�”、正确配对
236	// 的代理项转义与同一字符的合法转义写法都照常接受；已经转义的反斜杠
237	// （\\）其后的 uD800 只是普通文字，不是代理项转义。
238	func checkRecordText(data []byte) error {
239		if !utf8.Valid(data) {
240			return errors.New("记录包含无效 UTF-8 字节，文本编码损坏")
241		}
242		// 只需定位字符串字面量并检查其中的 \u 转义；JSON 其余部分的合法性
243		// 由 json.Unmarshal 判断。data 已是合法 UTF-8，多字节字符中不可能
244		// 出现 '"' 或 '\\' 字节。
245		i := 0
246		for i < len(data) {
247			if data[i] != '"' {
248				i++
249				continue
250			}
251			i++ // 进入字符串字面量
252			for i < len(data) {
253				c := data[i]
254				if c == '"' {
255					i++
256					break
257				}
258				if c != '\\' {
259					i++
260					continue
261				}
262				// 转义序列：\\ 是已转义的反斜杠，其后的 uD800 只是普通文字。
263				i++
264				if i >= len(data) {
265					break // 截断的转义由 json.Unmarshal 报解析错误
266				}
267				esc := data[i]
268				i++
269				if esc != 'u' {
270					continue
271				}
272				if i+4 > len(data) {
273					break // 截断的转义由 json.Unmarshal 报解析错误
274				}
275				v, ok := hex4(data[i : i+4])
276				i += 4
277				if !ok {
278					continue // 非法十六进制由 json.Unmarshal 报解析错误
279				}
280				switch {
281				case v >= 0xD800 && v <= 0xDBFF:
282					// 高位代理项必须紧接一个低位代理项转义才完整。
283					if i+6 <= len(data) && data[i] == '\\' && data[i+1] == 'u' {
284						if lo, ok := hex4(data[i+2 : i+6]); ok && lo >= 0xDC00 && lo <= 0xDFFF {
285							i += 6
286							continue
287						}
288					}
289					return fmt.Errorf("记录包含未配对的高位代理项转义 \\u%04X，Unicode 转义损坏", v)
290				case v >= 0xDC00 && v <= 0xDFFF:
291					return fmt.Errorf("记录包含单独出现的低位代理项转义 \\u%04X，Unicode 转义损坏", v)
292				}
293			}
294		}
295		return nil
296	}
297	
298	// hex4 解析 4 位十六进制数字（\uXXXX 转义的码位部分）。
299	func hex4(b []byte) (int, bool) {
300		v := 0
301		for _, c := range b {
302			v <<= 4
303			switch {
304			case c >= '0' && c <= '9':
305				v |= int(c - '0')
306			case c >= 'a' && c <= 'f':
307				v |= int(c-'a') + 10
308			case c >= 'A' && c <= 'F':
309				v |= int(c-'A') + 10
310			default:
311				return 0, false
312			}
313		}
314		return v, true
315	}
316	
317	func syncDir(dir string) error {
318		d, err := os.Open(dir)
319		if err != nil {
320			return err
321		}
322		defer d.Close()
323		return d.Sync()
324	}
325	
326	// writeAtomic 把 data 写入 dir 下的 name：同目录临时文件、fsync、
327	// 原子改名，保证崩溃后只会看到旧文件或新文件。
328	func writeAtomic(dir, name string, data []byte) error {
329		tmp := filepath.Join(dir, ".tmp-"+name+"-"+randomSuffix())
330		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
331		if err != nil {
332			return err
333		}
334		clean := true
335		defer func() {
336			if clean {
337				os.Remove(tmp)
338			}
339		}()
340		if _, err := f.Write(data); err != nil {
341			f.Close()
342			return err
343		}
344		if err := f.Sync(); err != nil {
345			f.Close()
346			return err
347		}
348		if err := f.Close(); err != nil {
349			return err
350		}
351		final := filepath.Join(dir, name)
352		if err := os.Rename(tmp, final); err != nil {
353			return err
354		}
355		clean = false
356		return syncDir(dir)
357	}
358	
359	func randomSuffix() string {
360		var b [8]byte
361		_, _ = rand.Read(b[:])
362		return hex.EncodeToString(b[:])
363	}
