1	package world
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"reflect"
8		"strings"
9		"testing"
10	)
11	
12	// rewriteRecordDuplicate 对记录文件做一次原始文本替换（在同一对象内注入
13	// 同名字段），并按替换后解码（同名字段后者覆盖前者）的内容重算校验和写回，
14	// 模拟“同一对象内出现重复名称、解码后的世界合法且校验和匹配”的损坏记录。
15	func rewriteRecordDuplicate(t *testing.T, a *Archive, id RecordID, from, to string) {
16		t.Helper()
17		path := recordPath(a.dir, id)
18		raw, err := os.ReadFile(path)
19		if err != nil {
20			t.Fatal(err)
21		}
22		var env envelope
23		if err := json.Unmarshal(raw, &env); err != nil {
24			t.Fatal(err)
25		}
26		oldSum := env.Checksum
27		if !strings.Contains(string(raw), from) {
28			t.Fatalf("记录 %s 中找不到待替换文本 %q", id, from)
29		}
30		corrupted := strings.Replace(string(raw), from, to, 1)
31		// encoding/json 对同名字段静默采用后一个值，解析仍然成功；按解码结果
32		// 重算校验和，使重复名称在校验和下被掩盖。
33		var cenv envelope
34		if err := json.Unmarshal([]byte(corrupted), &cenv); err != nil {
35			t.Fatalf("测试前提：注入重复名称后的记录应仍可被 encoding/json 解析: %v", err)
36		}
37		corrupted = strings.Replace(corrupted, oldSum, computeChecksum(&cenv), 1)
38		if err := os.WriteFile(path, []byte(corrupted), 0o600); err != nil {
39			t.Fatal(err)
40		}
41	}
42	
43	// assertDuplicateNameCorrupt 断言 err 是保留了被拒绝记录标识、且说明名称
44	// 重复的 *CorruptError，而不是版本拒绝或其它错误。
45	func assertDuplicateNameCorrupt(t *testing.T, err error, id RecordID) {
46		t.Helper()
47		ce, ok := err.(*CorruptError)
48		if !ok {
49			t.Fatalf("应为 *CorruptError，得到 %T: %v", err, err)
50		}
51		if ce.Record != id {
52			t.Fatalf("CorruptError 应保留被拒绝的记录标识 %s，得到 %q", id, ce.Record)
53		}
54		if !strings.Contains(ce.Error(), "重复") {
55			t.Fatalf("错误应说明名称重复: %v", ce)
56		}
57		if errors.As(err, new(*VersionRejectedError)) {
58			t.Fatalf("名称重复不应报成版本拒绝: %v", err)
59		}
60	}
61	
62	// TestLatestAndRecordDuplicateNameCorrupt 同一 JSON 对象内出现同名字段时，
63	// 无论两个值是否相同、采用后一个值后的世界是否合法、校验和是否匹配，Latest
64	// 与 Record 都必须把整条记录视为损坏，返回保留记录标识并说明名称重复的
65	// *CorruptError；即使规则版本不在可接受集合内也先报损坏。读取保持只读，
66	// 不修补这份记录，也不切换槽当前记录。
67	func TestLatestAndRecordDuplicateNameCorrupt(t *testing.T) {
68		cases := []struct {
69			name string
70			from string
71			to   string
72		}{
73			// 记录顶层字段，两个值相同也算重复。
74			{"顶层同值", `"format": 1,`, `"format": 1, "format": 1,`},
75			// 记录顶层字段，前者是矛盾值、后者写回合法值。
76			{"顶层异值", `"slotFirst": false,`, `"slotFirst": true, "slotFirst": false,`},
77			// 先写负时间片，再用同名字段写回合法时间片。
78			{"负时间片写回", `"Time": 1,`, `"Time": -5, "Time": 1,`},
79			// 世界规则中的字段。
80			{"规则版本", `"Version": "v1",`, `"Version": "v9", "Version": "v1",`},
81			// 角色对象中的字段。
82			{"角色标识", `"ID": "hero",`, `"ID": "villain", "ID": "hero",`},
83			// 物品条目中的字段。
84			{"物品名称", `"Item": "gold",`, `"Item": "key", "Item": "gold",`},
85			{"物品数量", `"Count": 1`, `"Count": -9, "Count": 1`},
86			// 名称到数值的携带上限对象。
87			{"携带上限", `"hero": 5,`, `"hero": 99, "hero": 5,`},
88			// 直接写出的名称与表示同一名称的 Unicode 转义（\u0049D）同为 "ID"。
89			{"Unicode转义同名", `"ID": "hero",`, `"\u0049D": "hero", "ID": "hero",`},
90			// 转义写在前：先以转义形式给出同一名称，再直接写出。
91			{"Unicode转义同名在前", `"ID": "hero",`, `"ID": "hero", "\u0049D": "hero",`},
92		}
93		for _, tc := range cases {
94			t.Run(tc.name, func(t *testing.T) {
95				a, _ := newTestArchive(t)
96				ids := saveN(t, a, "s", 1) // r1(time 1) r0(time 0)
97				rewriteRecordDuplicate(t, a, ids[0], tc.from, tc.to)
98				before := recordFileBytes(t, a, ids[0])
99	
100				_, err := a.Latest("s", []string{"v1"})
101				assertDuplicateNameCorrupt(t, err, ids[0])
102	
103				_, err = a.Record("s", ids[0], []string{"v1"})
104				assertDuplicateNameCorrupt(t, err, ids[0])
