111				if got := recordFileBytes(t, a, ids[0]); string(got) != string(before) {
112					t.Fatal("读取改写了名称重复的记录")
113				}
114				if p, err := a.readSlotPointerLocked("s"); err != nil || p.Latest != ids[0] {
115					t.Fatalf("槽指向不应改变: %+v err=%v", p, err)
116				}
117	
118				// 本槽完好的历史记录不受影响，仍可正常读取。
119				if _, err := a.Record("s", ids[1], []string{"v1"}); err != nil {
120					t.Fatalf("完好的历史记录应可读: %v", err)
121				}
122			})
123		}
124	}
