133		rewriteRecordDuplicate(t, a, ids[0], `"Time": 2,`, `"Time": -1, "Time": 2,`)
134		before := recordFileBytes(t, a, ids[0])
135	
136		// 浏览略过名称重复的最新记录，其余按保存生效次序列出。
