207		corruptChecksum(t, dir, ids[0])
208		corruptChecksum(t, dir, ids[1])
209		if _, err := a2.RecoverLatest("s", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
210			t.Fatalf("断裂处更老的记录不应进入候选，得到 %T: %v", err, err)
211		}
212	}
