214	// TestDistinctObjectsSameNameStillReadable 不同对象各自使用相同名称是正常
215	// 内容：两个角色各自有标识与物品、两个物品条目各自有名称与数量字段，不能
216	// 被误判为重复。字符串值中的文字和标点（包括看起来像对象内容的名称）不算
217	// 对象名称。合法中文名称及其 Unicode 转义写法、只改变缩进或字段排列但内容
218	// 未变的记录都照常可读。
219	func TestDistinctObjectsSameNameStillReadable(t *testing.T) {
220		a, _ := newTestArchive(t)
221		w, err := NewWorld(InitialData{
222			Seed: 7,
223			Rules: Rules{
224				Version:     "v1",
225				Locations:   []string{"大厅", "院子"},
226				Edges:       []Edge{{From: "大厅", To: "院子"}},
227				ItemKinds:   []string{"金币", "钥匙"},
228				CarryLimits: map[string]int{"英雄": 5},
229			},
230			Characters: []Character{
231				{ID: "英雄", Location: "大厅", Items: []CharacterItem{
232					{Item: "金币", Count: 1},
233					{Item: "钥匙", Count: 2},
234				}},
235				// 字符串值中的标点与文字不算对象名称。
236				{ID: `{"ID": 1, "Count": 2}`, Location: "院子"},
237				{ID: "Count", Location: "院子"},
238			},
239		})
240		if err != nil {
241			t.Fatalf("NewWorld: %v", err)
242		}
243		want := w.Snapshot()
244		info, err := a.Save("s", w)
245		if err != nil {
246			t.Fatalf("Save: %v", err)
247		}
248	
249		rec, err := a.Latest("s", []string{"v1"})
250		if err != nil {
251			t.Fatalf("不同对象各自使用相同名称的记录应可读: %v", err)
252		}
253		if !reflect.DeepEqual(rec.State, want) {
254			t.Fatalf("读回状态与保存前不一致:\n got %+v\nwant %+v", rec.State, want)
255		}
256	
257		// 把文件中的中文名称改写为 Unicode 转义写法：解析内容不变，也不与
258		// 直接写出的同名字符串值构成重复，记录应照常可读。
259		path := recordPath(a.dir, info.ID)
260		raw, err := os.ReadFile(path)
261		if err != nil {
262			t.Fatal(err)
263		}
264		s := strings.ReplaceAll(string(raw), "大厅", `\u5927\u5385`)
265		s = strings.ReplaceAll(s, "英雄", `\u82f1\u96c4`)
266		if err := os.WriteFile(path, []byte(s), 0o600); err != nil {
267			t.Fatal(err)
268		}
269		rec, err = a.Latest("s", []string{"v1"})
270		if err != nil {
271			t.Fatalf("合法转义写法的记录应可读: %v", err)
272		}
273		if !reflect.DeepEqual(rec.State, want) {
274			t.Fatalf("读回状态与保存前不一致:\n got %+v\nwant %+v", rec.State, want)
275		}
276	
277		// 只改变缩进与字段排列（经 map 重新序列化）但内容未变的记录仍可读。
278		var m map[string]any
279		if err := json.Unmarshal([]byte(s), &m); err != nil {
280			t.Fatal(err)
281		}
282		flat, err := json.Marshal(m)
283		if err != nil {
284			t.Fatal(err)
285		}
286		if err := os.WriteFile(path, flat, 0o600); err != nil {
287			t.Fatal(err)
288		}
289		rec, err = a.Latest("s", []string{"v1"})
290		if err != nil {
291			t.Fatalf("仅改变格式的记录应可读: %v", err)
292		}
293		if !reflect.DeepEqual(rec.State, want) {
294			t.Fatalf("读回状态与保存前不一致:\n got %+v\nwant %+v", rec.State, want)
295		}
296	}
