}
type CI struct{ Item string; Count int }
type Char struct {
	ID, Location string
	Items        []CI
}
type State struct {
	Seed       int64
	Rules      Rules
	Time       int
	Characters []Char
}
type Env struct {
	Format    int
	ID        string
	Parent    string
	SlotFirst bool
	Checksum  string
	State     State
}

func show(name, data string) {
	var e Env
	err := json.Unmarshal([]byte(data), &e)
	fmt.Printf("== %s err=%v\n", name, err)
	fmt.Printf("   format=%d id=%q slotFirst=%v state.seed=%d state.time=%d rules.version=%q limits=%v chars=%+v\n",
		e.Format, e.ID, e.SlotFirst, e.State.Seed, e.State.Time, e.State.Rules.Version, e.State.Rules.CarryLimits, e.State.Characters)
}

func main() {
	show("time-case", `{"format":1,"state":{"Time":-1,"time":0}}`)
