	show("carrylimit", `{"format":1,"state":{"rules":{"carryLimits":{"hero":5}}}}`)
	show("carrylimit-map-case", `{"format":1,"state":{"rules":{"carryLimits":{"Hero":5,"HERO":6}}}`)
	show("char-id-case", `{"format":1,"state":{"characters":[{"id":"a","ID":"b","location":"x"}]}}`)
	show("edge-from-case", `{"format":1,"state":{"rules":{"edges":[{"from":"a","To":"b"}]}}}`)
	show("seed-case", `{"format":1,"state":{"SEED":7,"seed":9}}`)
	show("unknown-extra", `{"format":1,"xyz":1,"XYZ":2}`)
	show("tag-lower-exact-vs-upper", `{"Format":1,"format":2}`)
	show("prefix", `{"format":1,"state":{"timex":1,"Time":2}}`)
	// underscore / other punctuation folding
	show("underscore", `{"format":1,"state":{"slot_first":1}}`)
	show("unicode-key", `{"format":1,"state":{"Tİme":1}}`)
}
