//
//   - 结构体型对象中，键按名称还原后忽略大小写归并（复刻 encoding/json
//     对无标签导出字段的匹配：先精确匹配，再按 foldName 匹配；本记录格式
//     没有在忽略大小写后互相冲突的固定字段）。因此 "Time" 与 "time"、
//     "time" 与 "Time" 都写入同一字段，同一对象内第二次出现即重复。
//   - 携带上限（CarryLimits）是名称到数值的映射而不是结构体：其键是实际
//     角色标识，"hero" 与 "HERO" 是两个不同角色，必须各自保留，绝不按
//     大小写合并或误报；判定与 map 解码一样按还原后的精确字符串比较。
//
// 名称按 JSON 转义还原后的字符串比较：直接写出的名称与表示同一名称的
// Unicode 转义（如 "Time" 与 "Time"）视为同一名称，不能借转义
// 绕过限制。判定严格按对象边界：两个不同对象各自使用相同名称是正常的
// （例如两个物品条目各自有数量字段），只有同一对象内一个固定字段被提供
// 两次才报错；字符串值中的文字与标点不算对象名称。记录文本已经通过
// json.Unmarshal 解析，这里只做重复字段判定，语法问题不再出现。
//
// 结构体对象中的未知键（读取时忽略、不属于任何固定字段）不参与判定：它们
// 不会遮住固定字段，也不会把互相冲突的内容读入状态。
func checkDuplicateNames(data []byte) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	// UseNumber 避免数值范围差异：这里只关心对象结构与名称，不解释数值。
	dec.UseNumber()
	// kind 描述解析栈中一层容器的固定字段归属方式。
	type kind int
	const (
		kArray      kind = iota // 数组：只占位，其中的字符串是值而不是名称
		kEnvelope               // 记录信封：format/id/parent/slotFirst/checksum/state
		kState                  // 世界状态：seed/rules/time/characters
		kRules                  // 规则：version/locations/edges/itemKinds/carryLimits
		kEdge                   // 道路：from/to
		kCharacter              // 角色：id/location/items
		kItem                   // 物品条目：item/count
		kStringMap              // 携带上限：键是实际角色标识，按精确字符串区分
	)
	// fixedFields 给出每个结构体型对象的固定字段，键为规范化（大写折叠）
	// 后的名称；这些字段与 types.go 中的结构体定义及 envelope 的 JSON 标签
	// 一一对应。
	fixedFields := map[kind]map[string]bool{
		kEnvelope: {"FORMAT": true, "ID": true, "PARENT": true, "SLOTFIRST": true,
			"CHECKSUM": true, "STATE": true},
		kState: {"SEED": true, "RULES": true, "TIME": true, "CHARACTERS": true},
		kRules: {"VERSION": true, "LOCATIONS": true, "EDGES": true,
			"ITEMKINDS": true, "CARRYLIMITS": true},
		kEdge:      {"FROM": true, "TO": true},
		kCharacter: {"ID": true, "LOCATION": true, "ITEMS": true},
		kItem:      {"ITEM": true, "COUNT": true},
	}
	// childKind 给出“某结构体对象的某固定字段的值是哪种容器”。
	childKind := map[kind]map[string]kind{
		kEnvelope: {"STATE": kState},
		kState:    {"RULES": kRules, "CHARACTERS": kArray},
		kRules:    {"EDGES": kArray, "ITEMKINDS": kArray, "LOCATIONS": kArray,
			"CARRYLIMITS": kStringMap},
		kCharacter: {"ITEMS": kArray},
	}
	// 数组元素的容器类型，按所属数组在父对象中的字段区分。
	arrayElemKind := map[[2]kind]kind{
		{kState, kArray}:     kCharacter, // state.characters
		{kRules, kArray}:     kEdge,      // rules.edges（见 elemField 区分）
		{kCharacter, kArray}: kItem,      // character.items
	}
	// frame 是解析栈中的一层容器。
	type frame struct {
		k        kind
		seen     map[string]bool // 已提供的字段或键（见 exact）
		exact    bool            // kStringMap 时按精确字符串，否则按折叠名称
		expectKey bool
	}
	var stack []*frame
	// elemField 记录数组上一层对象中该数组对应的字段名，以区分 rules 下
	// edges/locations/itemKinds 三类数组（后两类元素是标量，不产生对象）。
	var elemField []string
	// folded 复刻 encoding/json 的 foldName：ASCII 转大写，其余码位取其
	// Unicode 简单折叠集合中的最小码位；对本记录的 ASCII 固定字段与
	// strings.EqualFold 完全一致。
	folded := func(s string) string {
		var b strings.Builder
		b.Grow(len(s))
		for _, r := range s {
			if 'a' <= r && r <= 'z' {
				r -= 'a' - 'A'
			} else if r >= utf8.RuneSelf {
				for {
					r2 := utf8.SimpleFold(r)
					if r2 <= r {
						break
					}
					r = r2
				}
			}
			b.WriteRune(r)
		}
		return b.String()
	}
	// 一个值（标量或容器）结束后，父对象等待下一个键。
	markValueDone := func() {
		if n := len(stack); n > 0 {
			top := stack[n-1]
			if top.k != kArray && top.k != kStringMap || n > 0 && top.k == kStringMap && false {
			}
			if top.k != kArray {
				top.expectKey = true
			}
		}
	}
	_ = markValueDone
	_ = arrayElemKind
	_ = elemField
	_ = childKind
	_ = fixedFields
}

