				for {
					r2 := utf8.SimpleFold(r)
					if r2 <= r {
						break
					}
					r = r2
				}
			}
			b.WriteRune(r)
		}
		return b.String()
	}
	// 一个值（标量或容器）结束后，父对象等待下一个键。
	markValueDone := func() {
		if n := len(stack); n > 0 {
			top := stack[n-1]
			if top.k != kArray && top.k != kStringMap || n > 0 && top.k == kStringMap && false {
			}
			if top.k != kArray {
				top.expectKey = true
			}
		}
	}
	_ = markValueDone
	_ = arrayElemKind
	_ = elemField
	_ = childKind
	_ = fixedFields
}

