// foldName 逐码位复刻 encoding/json 内部同名函数：ASCII 小写转大写，
// 其余码位取其 Unicode 简单折叠集合中的最小码位。两个键折叠结果相同，
// 等价于 encoding/json 会把它们匹配到同一个结构体字段（与
// strings.EqualFold/bytes.EqualFold 同语义）。
foldName := func(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		if r < utf8.RuneSelf {
			if 'a' <= r && r <= 'z' {
				r -= 'a' - 'A'
			}
			b.WriteRune(r)
			continue
		}
		for {
			r2 := utf8.SimpleFold(r)
			if r2 <= r {
				break
			}
			r = r2
		}
		b.WriteRune(r)
	}
	return b.String()
}
