func TestHistoryRecoverySkipsCaseDuplicate(t *testing.T) {
	a, _ := newTestArchive(t)
	ids := saveN(t, a, "s", 2) // time 2, 1, 0
	rewriteRecordText(t, a, ids[0], `"Time": 2,`, `"Time": -1, "time": 2,`)
