package world

import (
	"encoding/json"
	"errors"
	"os"
	"reflect"
	"strings"
	"testing"
)

// rewriteRecordText 对记录文件做一次原始文本替换，并按替换后解码的内容
// 重算校验和写回，用来构造“解码后的世界合法且校验和匹配”的记录文本。
func rewriteRecordText(t *testing.T, a *Archive, id RecordID, from, to string) {
	t.Helper()
	path := recordPath(a.dir, id)
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var env envelope
	if err := json.Unmarshal(raw, &env); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(raw), from) {
		t.Fatalf("记录 %s 中找不到待替换文本 %q", id, from)
	}
	changed := strings.Replace(string(raw), from, to, 1)
	var cenv envelope
	if err := json.Unmarshal([]byte(changed), &cenv); err != nil {
		t.Fatalf("测试前提：替换后的记录应仍可被 encoding/json 解析: %v", err)
	}
	changed = strings.Replace(changed, env.Checksum, computeChecksum(&cenv), 1)
	if err := os.WriteFile(path, []byte(changed), 0o600); err != nil {
		t.Fatal(err)
	}
}

// TestZeroTimeCaseDuplicateRejected 任务描述中的原始情形：零时间片状态里
// 先写大写 "Time": -1 再写小写 "time": 0，解码结果是合法的零时间片状态
// 且按该状态重算的校验和匹配，但两个键会被读取为同一个固定字段，必须按
// 损坏拒绝；交换先后顺序同样拒绝。
func TestZeroTimeCaseDuplicateRejected(t *testing.T) {
	// 大写在前、小写在后：最终解码时间片为 0。
	a, _ := newTestArchive(t)
	ids := saveN(t, a, "s", 0) // 只有一份时间片为 0 的槽首记录
	rewriteRecordText(t, a, ids[0], `"Time": 0,`, `"Time": -1, "time": 0,`)
	_, err := a.Latest("s", []string{"v1"})
	assertDuplicateNameCorrupt(t, err, ids[0])
	_, err = a.Record("s", ids[0], []string{"v1"})
	assertDuplicateNameCorrupt(t, err, ids[0])
	// 版本不被接受也先报损坏。
	_, err = a.Latest("s", []string{"other"})
	assertDuplicateNameCorrupt(t, err, ids[0])

	// 小写在前、大写在后：交换顺序不改变判定。
	a2, _ := newTestArchive(t)
	ids2 := saveN(t, a2, "s", 0)
	rewriteRecordText(t, a2, ids2[0], `"Time": 0,`, `"time": -1, "Time": 0,`)
	_, err = a2.Latest("s", []string{"v1"})
	assertDuplicateNameCorrupt(t, err, ids2[0])
}

// TestCaseEscapeVariantsCollide 直接写法与 Unicode 转义写法在大小写维度
// 上也会相撞：大写 T 的转义写法与小写 time、小写 t 的转义写法与大写
// Time 都归并到同一个时间片字段。
func TestCaseEscapeVariantsCollide(t *testing.T) {
	cases := []struct {
		name string
		from string
		to   string
	}{
		// 是大写 T：先写大写 Time(-1) 再写小写 time(1)。
		{"转义大写在前", `"Time": 1,`, `"Time": -1, "time": 1,`},
		// 是小写 t：先写小写 time(-1) 再写大写 Time(1)。
		{"转义小写在前", `"Time": 1,`, `"time": -1, "Time": 1,`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			a, _ := newTestArchive(t)
			ids := saveN(t, a, "s", 1)
			rewriteRecordText(t, a, ids[0], tc.from, tc.to)
			_, err := a.Latest("s", []string{"v1"})
			assertDuplicateNameCorrupt(t, err, ids[0])
			_, err = a.Record("s", ids[0], []string{"v1"})
			assertDuplicateNameCorrupt(t, err, ids[0])
		})
	}
}

// TestAlternateCaseSingleFieldReadable 某个固定字段只出现一次时，换一种
// 大小写（与 JSON 标签/Go 名称不同的写法）仍是合法记录，无需重写旧记录。
// 这里把记录中各层级固定字段键整体改成另一种大小写（每个字段仍只出现
// 一次），解码内容不变；校验和只取决于解码后的内容，因此原校验和仍匹配，
// 必须照常读出完全相同的状态。
func TestAlternateCaseSingleFieldReadable(t *testing.T) {
	a, _ := newTestArchive(t)
	w := baseWorld(t)
	want := w.Snapshot()
	info, err := a.Save("s", w)
	if err != nil {
		t.Fatalf("Save: %v", err)
	}

	path := recordPath(a.dir, info.ID)
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	s := string(raw)
	// 每个固定字段在每个对象中只出现一次；整体换成另一种大小写写法，
	// 解码目标不变，校验和也不变。
	for _, key := range []string{
		`"State"`, `"Seed"`, `"Rules"`, `"Time"`, `"Characters"`,
		`"Version"`, `"Locations"`, `"Edges"`, `"ItemKinds"`, `"CarryLimits"`,
		`"From"`, `"To"`, `"ID"`, `"Location"`, `"Items"`,
		`"Item"`, `"Count"`,
	} {
		s = strings.ReplaceAll(s, key+":", strings.ToLower(key)+":")
	}
	var cenv envelope
	if err := json.Unmarshal([]byte(s), &cenv); err != nil {
		t.Fatalf("测试前提：换大小写键后的记录应可解析: %v", err)
	}
	if cenv.Checksum != info.ID && cenv.Checksum == "" {
		t.Fatal("测试前提：校验和不应被改动")
	}
	if err := os.WriteFile(path, []byte(s), 0o600); err != nil {
		t.Fatal(err)
	}

	rec, err := a.Latest("s", []string{"v1"})
	if err != nil {
		t.Fatalf("固定字段只出现一次时，大小写变体应当可读: %v", err)
	}
	if !reflect.DeepEqual(rec.State, want) {
		t.Fatalf("读回状态与保存前不一致:\n got %+v\nwant %+v", rec.State, want)
	}
}

