	// 只改第二个角色对象的 ID 键、第二个物品对象的 Count 键的大小写：
	// 与第一个对象中的同名字段分属不同对象，不构成重复。
	s = strings.Replace(s, `"ID": "q"`, `"id": "q"`, 1)
	s = strings.Replace(s, `"Count": 2`, `"count": 2`, 1)
	if err := os.WriteFile(path, []byte(s), 0o600); err != nil {
		t.Fatal(err)
	}

