	}
	// 只改键的大小写不改变解码内容，记录原有校验和必须仍然匹配——
	// 这正是旧记录无需重写即可继续读取的兼容性依据。
	if got := computeChecksum(&cenv); got != cenv.Checksum {
		t.Fatalf("只改键的大小写不应改变校验和: got %s want %s", got, cenv.Checksum)
	}
	if err := os.WriteFile(path, []byte(s), 0o600); err != nil {
		t.Fatal(err)
